B=[
('الْخُرُوجُ مِنْ طَنْجَةَ','Tanca’dan çıkış',[
('خَرَجَ أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ بَطُّوطَةَ مِنْ مَدِينَتِهِ طَنْجَةَ سَنَةَ خَمْسٍ وَعِشْرِينَ وَسَبْعِمِائَةٍ.','Ebû Abdullah Muhammed b. Battûta 725 yılında şehri Tanca’dan çıktı.'),
('وَكَانَ عُمُرُهُ اثْنَتَيْنِ وَعِشْرِينَ سَنَةً، وَقَصْدُهُ حَجُّ بَيْتِ اللَّهِ الْحَرَامِ وَزِيَارَةُ قَبْرِ الرَّسُولِ.','Yirmi iki yaşındaydı; amacı Beytullah’ı haccetmek ve Peygamber’in kabrini ziyaret etmekti.'),
('قَالَ: «خَرَجْتُ مُنْفَرِدًا، عَنْ غَيْرِ رَفِيقٍ آنَسُ بِصُحْبَتِهِ، وَلَا رَكْبٍ أَكُونُ فِي جُمْلَتِهِ.»','Dedi ki: “Sohbetiyle ünsiyet bulacağım bir yoldaş ya da içinde bulunacağım bir kafile olmadan tek başıma çıktım.”'),
('«فَفَارَقْتُ الْأَهْلَ وَالْأَوْطَانَ، كَمَا تُفَارِقُ الطُّيُورُ الْأَوْكَارَ.»','“Kuşların yuvalarından ayrılması gibi aileden ve yurttan ayrıldım.”'),
('وَكَانَ أَبَوَاهُ حَيَّيْنِ، فَحَزِنَا لِفِرَاقِهِ حُزْنًا شَدِيدًا.','Anne babası hayattaydı; onun ayrılığına çok üzüldüler.'),
('وَلَمْ يَكُنْ يَعْلَمُ أَنَّ رِحْلَتَهُ سَتَدُومُ نَحْوَ ثَلَاثِينَ سَنَةً، وَأَنَّهُ سَيَقْطَعُ أَكْثَرَ مِنْ مِائَةِ أَلْفِ كِيلُومِتْرٍ.','Yolculuğunun otuz yıla yakın süreceğini ve yüz bin kilometreden fazla yol katedeceğini bilmiyordu.')]),
('مِصْرُ','Mısır',[
('مَرَّ بِتُونِسَ وَطَرَابُلُسَ، ثُمَّ وَصَلَ إِلَى الْإِسْكَنْدَرِيَّةِ.','Tunus’tan ve Trablus’tan geçti, sonra İskenderiye’ye vardı.'),
('فَرَأَى مَنَارَتَهَا الْعَظِيمَةَ، وَقَدْ تَهَدَّمَ بَعْضُهَا.','Bir kısmı yıkılmış olan büyük fenerini gördü.'),
('ثُمَّ دَخَلَ الْقَاهِرَةَ، فَوَصَفَهَا بِأَنَّهَا «أُمُّ الْبِلَادِ»، كَثِيرَةُ الْعِمَارَةِ، تَمُوجُ مَوْجَ الْبَحْرِ بِسُكَّانِهَا.','Sonra Kahire’ye girdi ve onu “şehirlerin anası”, imarı çok, sakinleriyle deniz gibi dalgalanan bir şehir diye vasfetti.'),
('وَرَأَى النِّيلَ، فَقَالَ: «نِيلُ مِصْرَ يَفْضُلُ أَنْهَارَ الْأَرْضِ عُذُوبَةَ مَذَاقٍ وَاتِّسَاعَ قُطْرٍ.»','Nil’i gördü ve dedi ki: “Mısır’ın Nil’i, tadının tatlılığı ve genişliğiyle yeryüzünün ırmaklarından üstündür.”'),
('وَزَارَ الْمَسَاجِدَ وَالْمَدَارِسَ، وَلَقِيَ الْعُلَمَاءَ وَالصَّالِحِينَ.','Mescitleri ve medreseleri ziyaret etti, âlimler ve salihlerle görüştü.'),
('وَكَانَ مِنْ عَادَتِهِ أَنْ يَكْتُبَ أَسْمَاءَ مَنْ لَقِيَهُمْ، وَيَحْفَظَ أَخْبَارَهُمْ.','Görüştüğü kişilerin adlarını yazmak ve haberlerini akılda tutmak âdetiydi.')]),
('الْحَجُّ','Hac',[
('سَارَ مِنْ مِصْرَ إِلَى الشَّامِ، فَزَارَ الْقُدْسَ وَدِمَشْقَ.','Mısır’dan Şam’a gitti; Kudüs’ü ve Dımaşk’ı ziyaret etti.'),
('وَأَعْجَبَهُ جَامِعُ بَنِي أُمَيَّةَ بِدِمَشْقَ، وَقَالَ: «هُوَ أَعْظَمُ مَسَاجِدِ الدُّنْيَا إِتْقَانًا.»','Dımaşk’taki Emevî Camii onu hayran bıraktı ve dedi ki: “O, işçiliğiyle dünyanın en büyük mescididir.”'),
('ثُمَّ خَرَجَ مَعَ الرَّكْبِ الشَّامِيِّ إِلَى الْحِجَازِ، فِي حَرِّ الصَّحْرَاءِ.','Sonra çölün sıcağında Şam kafilesiyle Hicaz’a çıktı.'),
('فَزَارَ الْمَدِينَةَ الْمُنَوَّرَةَ، وَصَلَّى فِي مَسْجِدِ الرَّسُولِ.','Medine-i Münevvere’yi ziyaret etti ve Peygamber’in mescidinde namaz kıldı.'),
('ثُمَّ دَخَلَ مَكَّةَ، فَطَافَ بِالْكَعْبَةِ، وَبَكَى مِنَ الْفَرَحِ.','Sonra Mekke’ye girdi, Kâbe’yi tavaf etti ve sevinçten ağladı.'),
('وَلَمَّا أَتَمَّ حَجَّهُ، لَمْ يَرْجِعْ إِلَى بَلَدِهِ، بَلْ عَزَمَ عَلَى أَنْ يَرَى بِلَادَ الْأَرْضِ.','Haccını tamamlayınca memleketine dönmedi; aksine yeryüzünün ülkelerini görmeye karar verdi.'),
('وَكَانَ قَدْ نَذَرَ أَلَّا يَسْلُكَ طَرِيقًا مَرَّتَيْنِ مَا اسْتَطَاعَ.','Elinden geldikçe bir yoldan iki kez geçmemeye ahdetmişti.')]),
('الْأَنَاضُولُ','Anadolu',[
('رَكِبَ الْبَحْرَ إِلَى بِلَادِ الرُّومِ، أَيِ الْأَنَاضُولِ.','Denize açılıp Rum diyarına, yani Anadolu’ya gitti.'),
('فَقَالَ: «هَذِهِ الْبِلَادُ مِنْ أَحْسَنِ أَقَالِيمِ الدُّنْيَا، وَأَهْلُهَا أَحْسَنُ النَّاسِ صُوَرًا وَأَنْظَفُهُمْ مَلَابِسَ.»','Dedi ki: “Bu ülke dünyanın en güzel bölgelerindendir; halkı insanların en güzel yüzlüsü ve en temiz giyimlisidir.”'),
('وَأَعْجَبَهُ كَرَمُ الْأَخِيَّةِ، وَهُمْ جَمَاعَاتٌ مِنَ الشُّبَّانِ يُكْرِمُونَ الْغُرَبَاءَ.','Gariplere ikram eden genç topluluklarından oluşan Ahîlerin cömertliği onu hayran bıraktı.'),
('فَكَانُوا يَتَسَابَقُونَ إِلَيْهِ، كُلٌّ يُرِيدُ أَنْ يَكُونَ هُوَ ضَيْفَهُ.','Herkes onun kendi misafiri olmasını isteyerek ona koşuşuyordu.'),
('وَلَقِيَ فِي بُورْصَةَ السُّلْطَانَ أُورْخَانَ بْنَ عُثْمَانَ، وَوَصَفَهُ بِأَنَّهُ أَكْبَرُ مُلُوكِ التُّرْكُمَانِ مَالًا وَبِلَادًا.','Bursa’da Osman oğlu Sultan Orhan’la görüştü ve onu Türkmen hükümdarlarının malca ve toprakça en büyüğü diye vasfetti.'),
('وَزَارَ قُونِيَةَ، وَرَأَى ضَرِيحَ جَلَالِ الدِّينِ الرُّومِيِّ.','Konya’yı ziyaret etti ve Celâleddîn-i Rûmî’nin türbesini gördü.')]),
]
